import os, json, math

BASE = 'storage/shared/atlas/analysis/cross_lineage/meta_edge_monitor'
INP  = os.path.join(BASE, 'predictive_scenarios_summary_corr.json')
OUTJ = os.path.join(BASE, 'ci_corr_report.json')  # overwrite
OUTT = os.path.join(BASE, 'ci_corr_report.txt')

def load_json(p):
    if not os.path.exists(p): return None
    try:
        with open(p,'r',encoding='utf-8') as f: return json.load(f)
    except Exception: return None

def in_01(x): return 0.0 <= x <= 1.0
def nondecreasing(a, tol=1e-9): return all(a[i+1] + tol >= a[i] for i in range(len(a)-1))
def diffs(a): return [a[i+1]-a[i] for i in range(len(a)-1)]
def mad(a):  # mean absolute difference
    d = diffs(a)
    return sum(abs(x) for x in d)/len(d) if d else 0.0

def write_reports(rep):
    os.makedirs(BASE, exist_ok=True)
    with open(OUTJ,'w',encoding='utf-8') as f: json.dump(rep, f, ensure_ascii=False, indent=2)
    with open(OUTT,'w',encoding='utf-8') as f:
        f.write(f"version: {rep.get('version')}\n")
        f.write(f"status: {'OK' if rep.get('ok') else 'FAIL'}\n")
        for k in ['horizons','len_any','len_all','len_one','N','seed','rho']:
            if k in rep: f.write(f"{k}: {rep[k]}\n")
        for k in ['checks','notes','errors','warnings']:
            if k in rep: f.write(f"{k}: {rep[k]}\n")
    print(json.dumps({"status":"ok","ok":rep.get('ok',False),"version":rep.get('version'),"report_json":OUTJ,"report_txt":OUTT}))

def main():
    d = load_json(INP)
    rep = {"version":"1.2","input":INP,"ok":False,"errors":[],"warnings":[],"checks":[]}

    if not isinstance(d, dict):
        rep["errors"].append("input_not_json_dict"); return write_reports(rep)

    # meta (if present)
    if "N" in d: rep["N"] = d["N"]
    if "seed" in d: rep["seed"] = d["seed"]
    if "rho" in d: rep["rho"] = d["rho"]

    # horizons
    H = None
    if isinstance(d.get("horizons"), list): H = len(d["horizons"])
    elif isinstance(d.get("horizons"), int): H = int(d["horizons"])
    elif isinstance(d.get("H"), int): H = int(d["H"])
    if not H or H < 1:
        rep["errors"].append("invalid_or_missing_horizons"); return write_reports(rep)
    rep["horizons"] = H

    # arrays
    keys = {"any":"p_any_corr","all":"p_all_corr","one":"p_exactly_one_corr"}
    arr = {}
    for name,key in keys.items():
        v = d.get(key)
        if not isinstance(v, list) or len(v)!=H:
            rep["errors"].append(f"missing_or_wrong_length:{key}")
        else:
            try: arr[name] = [float(x) for x in v]
            except Exception: rep["errors"].append(f"non_numeric:{key}")
    if rep["errors"]: return write_reports(rep)

    rep["len_any"], rep["len_all"], rep["len_one"] = len(arr["any"]), len(arr["all"]), len(arr["one"])

    # bounds
    for name in ["any","all","one"]:
        bad = [i for i,x in enumerate(arr[name]) if not in_01(x)]
        if bad: rep["errors"].append(f"out_of_bounds:{name}:{bad[:5]}{'...' if len(bad)>5 else ''}")
        else:   rep["checks"].append(f"bounds_ok:{name}")
    if rep["errors"]: return write_reports(rep)

    # all ≤ any
    bad = [i for i,(a,an) in enumerate(zip(arr["all"],arr["any"])) if a > an + 1e-9]
    if bad: rep["warnings"].append(f"all_exceeds_any_at:{bad[:5]}{'...' if len(bad)>5 else ''}")
    else:   rep["checks"].append("all_le_any_ok")

    # monotonic (nondecreasing) any/all
    if nondecreasing(arr["any"]): rep["checks"].append("monotone_nondecreasing:any")
    else: rep["warnings"].append("non_monotone:any")
    if nondecreasing(arr["all"]): rep["checks"].append("monotone_nondecreasing:all")
    else: rep["warnings"].append("non_monotone:all")

    # variance/trend checks (MAD on first half vs second half; warn if later noisier by >25%)
    def split_mad(a):
        if len(a)<4: return None
        mid = len(a)//2
        mad1, mad2 = mad(a[:mid+1]), mad(a[mid:])
        return (mad1, mad2)
    for name in ["any","all"]:
        m = split_mad(arr[name])
        if m:
            mad1, mad2 = m
            if mad2 > 1.25*(mad1 + 1e-12):
                rep["warnings"].append(f"variance_increase:{name}:mad2>{1.25}*mad1 ({mad2:.4g}>{mad1:.4g})")
            else:
                rep["checks"].append(f"variance_ok:{name}:mad2≤1.25*mad1 ({mad2:.4g}≤{mad1:.4g})")

    # optional indep ≤ corr when all rhos ≥ 0 and indep present
    rho = d.get("rho") or {}
    try:
        rhos = [float(rho.get(k,0.0)) for k in ["sd","se","de"]]
    except Exception:
        rhos = []
    nonneg = (len(rhos)==3 and all(x>=0.0 for x in rhos))
    if nonneg and all(k in d for k in ["p_any","p_all"]):
        try:
            any_i = [float(x) for x in d["p_any"]]
            all_i = [float(x) for x in d["p_all"]]
            if len(any_i)==H and len(all_i)==H:
                if any(xc+1e-9 < xi for xc,xi in zip(arr["any"], any_i)):
                    rep["warnings"].append("indep_gt_corr:any (unexpected with nonnegative rhos)")
                else:
                    rep["checks"].append("indep_le_corr:any")
                if any(xc+1e-9 < xi for xc,xi in zip(arr["all"], all_i)):
                    rep["warnings"].append("indep_gt_corr:all (unexpected with nonnegative rhos)")
                else:
                    rep["checks"].append("indep_le_corr:all")
        except Exception:
            rep["warnings"].append("indep_compare_failed")

    rep["ok"] = len(rep["errors"])==0
    rep["notes"] = "CI v1.2 adds variance/trend checks and optional indep≤corr bounds when rhos≥0."
    return write_reports(rep)

if __name__ == "__main__":
    main()
